<?php
if (!defined('ABSPATH')) exit;
class CC_Media {
 public static function handle($file){if(empty($file)||$file['error']===UPLOAD_ERR_NO_FILE)return 0;if($file['error']!==UPLOAD_ERR_OK||$file['size']>5*1024*1024)return new WP_Error('invalid_image','تصویر باید JPG، PNG یا WebP و حداکثر ۵ مگابایت باشد',array('status'=>400));$mime=wp_get_image_mime($file['tmp_name']);if(!in_array($mime,array('image/jpeg','image/png','image/webp'),true))return new WP_Error('invalid_mime','نوع واقعی تصویر مجاز نیست',array('status'=>400));require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/image.php';$upload=wp_handle_upload($file,array('test_form'=>false,'mimes'=>array('jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp')));if(isset($upload['error']))return new WP_Error('upload_failed',$upload['error'],array('status'=>400));$editor=wp_get_image_editor($upload['file']);if(is_wp_error($editor))return $upload;$editor->resize(1600,1600,false);$dest=preg_replace('/\.(jpe?g|png|webp)$/i','.webp',$upload['file']);$saved=$editor->save($dest,'image/webp');if(!is_wp_error($saved)){if($dest!==$upload['file'])@unlink($upload['file']);$upload['file']=$dest;$upload['url']=preg_replace('/\.[^.]+$/','.webp',$upload['url']);$upload['type']='image/webp';}$id=wp_insert_attachment(array('post_mime_type'=>'image/webp','post_title'=>sanitize_file_name(pathinfo($dest,PATHINFO_FILENAME)),'post_status'=>'inherit'),$upload['file']);if(!is_wp_error($id)){wp_update_attachment_metadata($id,wp_generate_attachment_metadata($id,$upload['file']));return $id;}return $upload;}
}
